const { Client } = require("@hubspot/api-client");

const hubspotClient = new Client({
  accessToken: $vars.discount_generator_apikey,
});
const email = $("is_empty?").all()[0].json.email;
let contact_data;
let company_data;
owners = {
  190043241: "Alejandro Beoutis",
  168849498: "Alesandra Zegarra",
  881523891: "Mhairi Macleod",
  1599694573: "Isabella Albarrán",
  86664709: "Federico Rivadeneira",
  77676408: "Victoria Córdova",
  168843586: "Martha Kennedy",
  231227222: "Lorena Muñoz",
  79261135: "Enya Solmaz",
  166784099: "Jennifer Aranguren",
  333845834: "Camila Gutierrez",
  168858112: "Ricardo Soltero",
  87653375: "Mariajose Hernandez",
};
//contact data
contact_data = await hubspotClient.crm.contacts.searchApi.doSearch({
  filterGroups: [
    {
      filters: [
        {
          value: email,
          propertyName: "hs_additional_emails",
          operator: "CONTAINS_TOKEN",
        },
      ],
    },
    {
      filters: [
        {
          value: email,
          propertyName: "email",
          operator: "EQ",
        },
      ],
    },
  ],
  sorts: [],
  properties: [
    "hubspot_owner_id",
    "type_of_contact",
    "contact_position__c",
    "times_traveled",
    "founder_member",
    "type_of_involvement",
  ],
  limit: 1,
  after: 0,
});

if (contact_data.results.length > 0) {
  company_data = await hubspotClient.crm.companies.searchApi.doSearch({
    filterGroups: [
      {
        filters: [
          {
            value: contact_data.results[0].id,
            propertyName: "associations.contact",
            operator: "EQ",
          },
        ],
      },
    ],
    sorts: [],
    properties: ["name", "school_type__c", "lifecyclestage"],
    limit: 1,
    after: 0,
  });
}

return {
  positon: contact_data?.results[0]?.properties.contact_position__c || null,
  owner: owners[contact_data?.results[0]?.properties.hubspot_owner_id] || null,
  times_traveled: contact_data?.results[0]?.properties.times_traveled || null,
  type_of_contact: contact_data?.results[0]?.properties.type_of_contact || null,
  founder_member: contact_data?.results[0]?.properties.founder_member || null,
  type_of_involvement:
    contact_data?.results[0]?.properties.type_of_involvement || null,
  type_of_company: company_data?.results[0]?.properties.school_type__c || null,
  chapter_name: company_data?.results[0]?.properties.name || null,
  company_lifecycle:
    company_data?.results[0]?.properties.lifecyclestage || null,
};

const data = $("avatar_lookup").all()[0].json;
const tags = [];
const lifecycle_stages = {
  23878512: true,
  23925576: true,
  23925577: true,
  23926968: true,
};
//Check for position
if (data.positon) {
  if (data.positon.includes("President")) {
    tags.push("Chapter President");
  }
  tags.push("E-boarder");
} else {
  if (data.company_lifecycle) {
    if (lifecycle_stages[data.company_lifecycle] || false) {
      tags.push("General Member");
    }
  }
}

//Check for type of contact
if (data.type_of_contact) {
  if (data.type_of_contact.includes("College Student"))
    tags.push("College Student");
  if (data.type_of_contact.includes("High School Student"))
    tags.push("High School Student");
  if (data.type_of_contact.includes("Parent")) tags.push("Parent");
  if (data.type_of_contact.includes("Professor")) tags.push("Professor");
  if (data.type_of_contact.includes("Graduate")) tags.push("Alumni");
} else {
  if (data.type_of_company) {
    if (
      data.type_of_company.includes("University") ||
      data.type_of_company.includes("Community College") ||
      data.type_of_company.includes("CGEP")
    )
      tags.push("College Unknown");
    if (data.type_of_company.includes("High School"))
      tags.push("High School Unknown");
  }
}

//Check for times traveled
if (data.times_traveled > 0) tags.push("SLT Traveler");
if (data.times_traveled > 1) tags.push("Recurring Traveler");

//Check for expansion founder
if (data.founder_member > 0) tags.push("Chapter Founder");

//Check for donations
if (data.type_of_involvement) {
  if (data.type_of_involvement.includes("donor")) tags.push("Donor");
}
return { tags: tags.join() };

